class Solution {
public:
    vector<int> minimumCost(int n, vector<vector<int>>& edges, vector<vector<int>>& query) {
        vector<int> parent(n);
        vector<int> and_val(n, (1 << 30) - 1);
        iota(parent.begin(), parent.end(), 0);

        auto find = [&](auto& self, int i) -> int {
            if (parent[i] == i) return i;
            return parent[i] = self(self, parent[i]);
        };

        auto unite = [&](int i, int j, int w) {
            int root_i = find(find, i);
            int root_j = find(find, j);
            if (root_i != root_j) {
                parent[root_i] = root_j;
                and_val[root_j] &= and_val[root_i] & w;
            } else {
                and_val[root_j] &= w;
            }
        };

        for (const auto& e : edges) {
            unite(e[0], e[1], e[2]);
        }

        vector<int> ans;
        for (const auto& q : query) {
            int s = q[0], t = q[1];
            if (s == t) {
                ans.push_back(0);
            } else {
                int rs = find(find, s), rt = find(find, t);
                if (rs != rt) ans.push_back(-1);
                else ans.push_back(and_val[rs]);
            }
        }
        return ans;
    }
};

class Solution {
    public int[] minimumCost(int n, int[][] edges, int[][] query) {
        int[] parent = new int[n];
        int[] andVal = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            andVal[i] = (1 << 30) - 1;
        }

        for (int[] e : edges) {
            int rootU = find(parent, e[0]);
            int rootV = find(parent, e[1]);
            if (rootU != rootV) {
                parent[rootU] = rootV;
                andVal[rootV] &= andVal[rootU] & e[2];
            } else {
                andVal[rootV] &= e[2];
            }
        }

        int[] ans = new int[query.length];
        for (int i = 0; i < query.length; i++) {
            int s = query[i][0], t = query[i][1];
            if (s == t) {
                ans[i] = 0;
            } else {
                int rs = find(parent, s);
                int rt = find(parent, t);
                if (rs != rt) ans[i] = -1;
                else ans[i] = andVal[rs];
            }
        }
        return ans;
    }

    private int find(int[] parent, int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent, parent[i]);
    }
}

var minimumCost = function(n, edges, query) {
    const parent = Array.from({length: n}, (_, i) => i);
    const andVal = new Array(n).fill((1 << 30) - 1);

    function find(i) {
        if (parent[i] === i) return i;
        return parent[i] = find(parent[i]);
    }

    function unite(i, j, w) {
        const rootI = find(i);
        const rootJ = find(j);
        if (rootI !== rootJ) {
            parent[rootI] = rootJ;
            andVal[rootJ] &= andVal[rootI] & w;
        } else {
            andVal[rootJ] &= w;
        }
    }

    for (const [u, v, w] of edges) {
        unite(u, v, w);
    }

    const ans = [];
    for (const [s, t] of query) {
        if (s === t) {
            ans.push(0);
        } else {
            const rs = find(s), rt = find(t);
            if (rs !== rt) ans.push(-1);
            else ans.push(andVal[rs]);
        }
    }
    return ans;
};
